FWeaponTable FMultiTargetData::WeaponStorage;
FArmourTable FMultiTargetData::ArmourStorage;
FTrinketTable FMultiTargetData::TrinketStorage;
FMountTable FMultiTargetData::MountStorage;
FBannerTable FMultiTargetData::BannerStorage;
FHolderTable FMultiTargetData::HolderStorage;

TArray<uint8> FMultiTargetData::EncryptionKey;
TArray<uint8> FMultiTargetData::MacKey;
bool FMultiTargetData::bVerifyMac = true;



FWeaponRow UMultiTargetDataLibrary::GetWeaponRow(int32 Key, bool& bFound)
{
    const FWeaponRow* Found = FMultiTargetData::Weapon().FindByIndex(Key);

    bFound = Found != nullptr;

    // A copy, because Blueprint takes a struct by value and the row belongs to the table.
    // A default one when the key is not there, which is why bFound is not decoration.
    return Found != nullptr ? *Found : FWeaponRow();
}

int32 UMultiTargetDataLibrary::GetWeaponRowCount()
{
    return FMultiTargetData::Weapon().Records().Num();
}

FWeaponRow UMultiTargetDataLibrary::GetWeaponRowAt(int32 Position, bool& bFound)
{
    const TArray<FWeaponRow>& Rows = FMultiTargetData::Weapon().Records();

    bFound = Rows.IsValidIndex(Position);

    return bFound ? Rows[Position] : FWeaponRow();
}


