bool UMultiTargetDataLibrary::ReadAll(const FString& BasePath, const FString& FileExtension)
{
    return FMultiTargetData::ReadAll(BasePath, FileExtension);
}

bool FMultiTargetData::ReadAll(const FString& BasePath, const FString& FileExtension)
{
    // Read into tables of their own and moved into place at the end. Reading again is a
    // refresh - a patched .pak, a downloaded table - and one that fails on the third file
    // must not leave the first two replaced and the rest as they were.
    FWeaponTable LoadedWeapon;

    if (!LoadedWeapon.Read(FPaths::Combine(BasePath, TEXT("Weapon") + FileExtension)))
    {
        return false;
    }
    FArmourTable LoadedArmour;

    if (!LoadedArmour.Read(FPaths::Combine(BasePath, TEXT("Armour") + FileExtension)))
    {
        return false;
    }
    FTrinketTable LoadedTrinket;

    if (!LoadedTrinket.Read(FPaths::Combine(BasePath, TEXT("Trinket") + FileExtension)))
    {
        return false;
    }
    FMountTable LoadedMount;

    if (!LoadedMount.Read(FPaths::Combine(BasePath, TEXT("Mount") + FileExtension)))
    {
        return false;
    }
    FBannerTable LoadedBanner;

    if (!LoadedBanner.Read(FPaths::Combine(BasePath, TEXT("Banner") + FileExtension)))
    {
        return false;
    }
    FHolderTable LoadedHolder;

    if (!LoadedHolder.Read(FPaths::Combine(BasePath, TEXT("Holder") + FileExtension)))
    {
        return false;
    }

    WeaponStorage = MoveTemp(LoadedWeapon);
    ArmourStorage = MoveTemp(LoadedArmour);
    TrinketStorage = MoveTemp(LoadedTrinket);
    MountStorage = MoveTemp(LoadedMount);
    BannerStorage = MoveTemp(LoadedBanner);
    HolderStorage = MoveTemp(LoadedHolder);

    return true;
}
